gcode_macro auto_feeding_batch.gcode:
{% set action = params.ACTION | default('') %}
{% set default_extruder = printer[printer.toolhead.extruder].extruder_index %}
{% set current_extruder = params.EXTRUDER | default(default_extruder) | int %}

{% if action == 'START' %}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder0_temp VALUE={printer['extruder'].target}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder1_temp VALUE={printer['extruder1'].target}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder2_temp VALUE={printer['extruder2'].target}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder3_temp VALUE={printer['extruder3'].target}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=doing VALUE=True
{% elif action == 'DOING' %}
{% if doing == False %}
{action_raise_error('{"coded": "0002-0531-0000-0024", "msg": "auto feeding batch has not yet begun or has already ended", "action": "none"}')}
{% else %}
AUTO_FEEDING_PREHEAT EXTRUDER={current_extruder}
{% if params.NEXT_EXTRUDER is defined %}
{% set next_extruder = params.NEXT_EXTRUDER | default(default_extruder) | int %}
AUTO_FEEDING_PREHEAT EXTRUDER={next_extruder}
{% endif %}
{% set extruder_temps = [extruder0_temp, extruder1_temp, extruder2_temp, extruder3_temp] %}
{% set restore_temp = extruder_temps[current_extruder] %}
AUTO_FEEDING {rawparams} RESTORE_TEMP={restore_temp}
{% endif %}
{% else %}
{% if doing == True %}
{% if printer['print_stats'].state == 'paused' or printer['print_stats'].state == 'printing' %}
M104 S{extruder0_temp} T0 A0
M104 S{extruder1_temp} T1 A0
M104 S{extruder2_temp} T2 A0
M104 S{extruder3_temp} T3 A0
{% else %}
M104 S0 T0 A0
M104 S0 T1 A0
M104 S0 T2 A0
M104 S0 T3 A0
{% endif %}
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=doing VALUE=False
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder0_temp VALUE=0
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder1_temp VALUE=0
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder2_temp VALUE=0
SET_GCODE_VARIABLE MACRO=AUTO_FEEDING_BATCH VARIABLE=extruder3_temp VALUE=0
{% endif %}
{% endif %}

